def _parse_annotation(annotation: str) -> List[Node]:
    """Parse type annotation."""
    def make_xref(text: str) -> addnodes.pending_xref:
        # NOTE: ``None`` is a singleton (not a class).  The Python domain
        # provides an ``obj`` role for such objects and the Python
        # documentation inventories expose ``None`` as a data object.
        #
        # Using ``class`` here prevents intersphinx from resolving the
        # reference (and may be swallowed by ``builtin_resolver``), resulting in
        # inconsistent output between ``autodoc_typehints='signature'`` and
        # ``autodoc_typehints='description'``.
        reftype = 'obj' if text == 'None' else 'class'
        return pending_xref('', nodes.Text(text),
                            refdomain='py', reftype=reftype, reftarget=text)

    def unparse(node: ast.AST) -> List[Node]:
        if isinstance(node, ast.Attribute):
            return [nodes.Text("%s.%s" % (unparse(node.value)[0], node.attr))]
        elif isinstance(node, ast.Expr):
            return unparse(node.value)
        elif isinstance(node, ast.Index):
            return unparse(node.value)

